import path from 'node:path'

const UPLOAD_DIRECTORY = '/srv/uploads'

export function upload_path(name: string): string {
	if (name.startsWith('..')) throw new Error(`refused upload name: ${name}`)

	return path.join(UPLOAD_DIRECTORY, name)
}

fixture_files.src/upload-path.test.ts:
import { expect, it } from 'vitest'
import { upload_path } from './upload-path'

it('places a name inside the upload directory', () => {
	expect(upload_path('photo.png')).toBe('/srv/uploads/photo.png')
})

it('refuses a name that climbs out', () => {
	expect(() => upload_path('../../etc/passwd')).toThrow()
})
